      { label: "Exam scoring and score reports", url: "https://learn.microsoft.com/en-us/credentials/certifications/exam-scoring-reports" },
      { label: "Exam sandbox", url: "https://aka.ms/examdemo" },
      { label: "Microsoft Q&A", url: "https://learn.microsoft.com/en-us/answers/products/" }
